<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { api,post,user } from '../api'
const password=ref(''),code=ref(''),nextPassword=ref(''),secret=ref(''),error=ref(''),sessions=ref<any[]>([]),busy=ref(false)
async function execute(action:()=>Promise<void>){busy.value=true;error.value='';try{await action()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function totp(action:string){await execute(async()=>{const response=await post('security/totp',{Action:action,Password:password.value,Code:code.value,Secret:''});if(action==='prepare')secret.value=response.secret;else user.value=null})}
async function changePassword(){await execute(async()=>{await post('password',{Password:password.value,Code:code.value,NewPassword:nextPassword.value});user.value=null})}
async function revoke(){if(!confirm('撤销全部会话并退出登录？'))return;await execute(async()=>{await post('sessions',{All:true});user.value=null})}
onMounted(async()=>{try{sessions.value=await api('sessions')}catch(e){error.value=String(e)}})
</script>
<template><p v-if="error" class="error">{{error}}</p><div class="dashboard-grid"><section class="card"><h2>账号安全</h2><label>当前密码<input v-model="password" type="password" autocomplete="current-password"></label><label>双因素验证码<input v-model="code" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></label><h2>修改密码</h2><form @submit.prevent="changePassword"><label>新密码<input v-model="nextPassword" type="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><button class="primary" :disabled="busy">修改密码并退出</button></form><h2 style="margin-top:24px">双因素认证</h2><div class="toolbar"><button :disabled="busy" @click="totp('prepare')">生成密钥</button><button class="primary" :disabled="busy" @click="totp('enable')">确认启用</button><button :disabled="busy" @click="totp('disable')">停用</button></div><div v-if="secret" class="notice wrap">在认证器中添加密钥：<code>{{secret}}</code>。五分钟内输入认证器验证码后点击确认启用。密钥仅在此展示，请妥善保管。</div></section><section class="card"><div class="section-head"><h2>登录会话</h2><button @click="revoke">全部撤销</button></div><div v-for="(s,index) in sessions" :key="index" class="list-row"><span>登录 {{new Date(s.created*1000).toLocaleString()}}<small class="block muted">最后活动 {{new Date(s.seen*1000).toLocaleString()}}</small></span></div><p class="muted small">修改密码、停用账号或更改权限都会撤销相关会话。</p></section></div></template>
